package com.cdac.cssip.auth.service; import com.cdac.cssip.auth.client.UserServiceClient; import com.cdac.cssip.auth.dto.AuthDtos.*; import com.cdac.cssip.auth.entity.ValidId; import com.cdac.cssip.auth.repository.ValidIdRepository; import com.cdac.cssip.common.enums.*; import com.cdac.cssip.common.security.JwtTokenService; import feign.FeignException; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional public class AuthService{private final UserServiceClient users;private final ValidIdRepository ids;private final PasswordEncoder encoder;private final JwtTokenService jwt;@Value("${internal.api-key}")String key;
 public RegisterResponse register(RegisterRequest r){ValidId v=ids.findByCdacId(r.cdacId()).orElseThrow(()->new IllegalArgumentException("Invalid CDAC ID"));if(v.isUsed())throw new IllegalArgumentException("CDAC ID already used");if(v.getRole()!=r.role())throw new IllegalArgumentException("Role does not match issued CDAC ID");var u=users.create(new UserServiceClient.CreateUser(r.cdacId(),r.fullName(),r.email(),encoder.encode(r.password()),r.role()),key);v.setUsed(true);return new RegisterResponse(u.id(),u.cdacId(),u.fullName(),u.email(),u.role(),u.status(),"Registration successful. Await admin approval.");}
 public LoginResponse login(LoginRequest r){UserServiceClient.UserView u;try{u=users.byCdac(r.cdacId(),key);}catch(FeignException e){throw new IllegalArgumentException("Invalid CDAC ID or password");}if(!encoder.matches(r.password(),u.password()))throw new IllegalArgumentException("Invalid CDAC ID or password");if(u.status()!=UserStatus.APPROVED)throw new IllegalArgumentException("Account is "+u.status()+". Admin approval is required.");return new LoginResponse(jwt.generate(u.id(),u.cdacId(),u.fullName(),u.role()),u.id(),u.cdacId(),u.fullName(),u.email(),u.role());}
 public ValidId add(CreateValidIdRequest r){if(ids.findByCdacId(r.cdacId()).isPresent())throw new IllegalArgumentException("CDAC ID already exists");return ids.save(ValidId.builder().cdacId(r.cdacId()).role(r.role()).used(false).build());}}
